document.addEventListener("DOMContentLoaded",()=>{const e=document.getElementById("readerFullscreenBtn"),n=document.getElementById("readerFrameWrap");e&&n&&(e.addEventListener("click",()=>{document.fullscreenElement?document.exitFullscreen?.():n.requestFullscreen?.()}),document.addEventListener("fullscreenchange",()=>{const n=e.querySelector("i");n.classList.toggle("fa-expand",!document.fullscreenElement),n.classList.toggle("fa-compress",!!document.fullscreenElement)}))});